'use strict';
(()=>{
const $=id=>document.getElementById(id),P=ArborPhoto;
let active=false,source=null,sourceName='photo',settings={...P.defaults},past=[],future=[],timer,previewWorker,revision=0,renderedRevision=-1,exporting=false,loadRevision=0,currentPreset='lichen';
const groups=[
 ['Изображение',[['amount','Сила обработки',0,100],['threshold','Порог силуэта',0,255],['softness','Мягкость границ',0,100],['contrast','Контраст',0,100],['edges','Проявление контуров',0,100],['detail','Масштаб деталей',0,100],['tones','Полутона',0,100],['color','Цвет исходного фото',0,100]]],
 ['Деформация',[['bend','Волны и изгибы',0,100],['wavelength','Размер волны',0,100],['flow','Текучесть',0,100],['stretch','Растяжение по ширине',-80,100],['zigzag','Ломаные сдвиги',0,100]]],
 ['Прорастание',[['branching','Побеги из контуров',0,100],['length','Длина побегов',0,100],['forks','Разветвление',0,100]]],
 ['Фактура',[['porosity','Выеденные поры',0,100],['poreSize','Размер пор',0,100],['grain','Зерно',0,100],['ragged','Рваный край',0,100],['bark','Древесная кора',0,100],['relief','Рельеф коры',0,100],['fibers','Продольные волокна',0,100],['dust','Пылевой ореол',0,100]]]
];
const rangeMap=Object.fromEntries(groups.flatMap(g=>g[1]).map(([key,,min,max])=>[key,{min,max}]));
const switcher=document.createElement('nav');switcher.className='mode-switch';switcher.setAttribute('aria-label','Режим мастерской');switcher.innerHTML='<button id="typeMode" class="active" aria-pressed="true">Aa <span>Леттеринг</span></button><button id="photoMode" aria-pressed="false">◈ <span>Фото</span><small>NEW</small></button>';document.querySelector('.topbar').after(switcher);
const area=document.createElement('main');area.id='photoWorkspace';area.className='workspace photo-workspace';area.hidden=true;
area.innerHTML=`<section class="studio photo-studio"><div class="studio-head"><div><span class="eyebrow">02 / ОРГАНИЧЕСКАЯ ФОТОЛАБОРАТОРИЯ</span><h1>Другая природа изображения<span>.</span></h1></div><button class="quiet compare" id="photoCompare">◐ До / после</button></div>
<div id="photoDrop" class="photo-drop"><div class="photo-drop-art">◈</div><h2>Дай изображению прорасти.</h2><p>Перетащи фото сюда или выбери файл.<br>Портрет, растение, предмет — начни с любого изображения.</p><button id="photoUploadEmpty" class="primary">Загрузить фото <span>↗</span></button><span class="photo-formats">JPG · PNG · WebP · AVIF</span><button id="photoDemo" class="text-button">Попробовать на демо-рисунке</button></div>
<div id="photoPreview" hidden><div class="photo-image-bar"><span id="photoName"></span><button id="photoReplace" class="text-button">Заменить фото ↗</button></div><div class="photo-stage-wrap" id="photoStageWrap"><div class="photo-stage" id="photoStage"><canvas id="photoOutput" aria-label="Обработанное фото"></canvas><div id="photoBefore"><canvas id="photoOriginal" aria-label="Исходное фото"></canvas></div><div id="photoSeam"></div></div><div id="photoBusy" role="status">Проявляем фактуру…</div></div><div class="photo-comparison"><label for="photoCompareRange">Оригинал / обработка</label><input id="photoCompareRange" type="range" min="0" max="100" value="0"><span id="photoDimensions"></span></div></div>
<input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp,image/avif" hidden>
<section class="preset-section"><div class="section-line"><h2>Характер изображения</h2><span>Один источник — пять интерпретаций</span></div><div class="photo-presets">${[['lichen','Лишайник','Поры / разрушение'],['wood','Древесина','Кора / побеги'],['liquid','Пластика','Текучесть / силуэт'],['dust','Пыль','Зерно / распыление'],['print','Отпечаток','Контуры / полутона']].map(([id,label,note],i)=>`<button data-photo-preset="${id}" class="photo-preset ${id==='lichen'?'active':''}"><span class="photo-swatch swatch-${id}">${['◌','≋','∿','⁙','◐'][i]}</span><strong>${label}</strong><small>${note}</small></button>`).join('')}</div></section><p class="reference-note photo-local">Фото остаётся на твоём устройстве. Леттеринг и фото хранятся в отдельных режимах; между ними можно переключаться.</p></section>
<aside class="inspector photo-inspector"><div class="photo-inspector-title"><span>Настройки фото</span><button id="photoShuffle" class="icon-btn" aria-label="Новая фактура фото">⤨</button></div><div class="inspector-scroll"><fieldset id="photoSettings" disabled><section class="control-section"><label class="field-label" for="photoSource">Из чего строить форму</label><select id="photoSource"><option value="dark">Тёмные участки</option><option value="light">Светлые участки</option><option value="edges">Только контуры</option><option value="tones">Все полутона</option></select><p class="letter-note">Начни с порога силуэта. Поры и побеги растут из выделенных участков.</p></section>${groups.map(([label,controls],i)=>`<section class="control-section"><details ${i===0||i===3?'open':''}><summary>${label}<span class="section-number">0${i+1}</span></summary><div class="controls">${controls.map(([key,label,min,max])=>`<div class="control"><div class="control-line"><label for="photo-${key}">${label}</label><input class="number-value" id="photo-n-${key}" aria-label="Фото — ${label}: значение" type="number" min="${min}" max="${max}" data-photo-param="${key}"></div><input id="photo-${key}" type="range" min="${min}" max="${max}" aria-label="Фото — ${label}" data-photo-param="${key}"></div>`).join('')}</div></details></section>`).join('')}<section class="control-section"><div class="section-title"><h2>Цвет и фон</h2></div><div class="color-row"><label>Форма<input id="photoInk" type="color" value="${settings.ink}"></label><label>Фон<input id="photoPaper" type="color" value="${settings.paper}"></label><button id="photoInvert" class="icon-btn" aria-label="Поменять цвета фото">⇄</button></div><label class="check-row"><input id="photoTransparent" type="checkbox">Прозрачный фон PNG</label><button id="photoReset" class="text-button">↺ Сбросить обработку</button></section></fieldset><div class="inspector-foot"><button id="photoSave" class="text-button">Сохранить фотопроект</button><button id="photoOpen" class="text-button">Открыть фотопроект</button><input id="photoProjectFile" type="file" accept=".json" hidden></div></div></aside>`;
document.querySelector('.workspace').after(area);
const dialog=document.createElement('dialog');dialog.id='photoExportDialog';dialog.innerHTML='<form method="dialog"><button class="close" aria-label="Закрыть экспорт фото">×</button></form><span class="eyebrow">ЗАБРАТЬ ИЗОБРАЖЕНИЕ</span><h2>Сохранить фото</h2><label class="field-label" for="photoExportSize">Размер по длинной стороне</label><select id="photoExportSize"><option value="1600">До 1600 px</option><option value="3000" selected>До 3000 px · размер источника</option><option value="900">До 900 px · быстрый экспорт</option></select><p id="photoExportHint">Пропорции исходного изображения сохраняются.</p><div class="export-options"><button id="photoPng"><strong>PNG ↗</strong><span>С прозрачностью, если она включена</span></button><button id="photoJpeg"><strong>JPG ↗</strong><span>С выбранным фоном · качество 95%</span></button></div>';document.body.append(dialog);
function notify(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
function setMode(photo){active=photo;document.body.classList.toggle('photo-mode',photo);area.hidden=!photo;document.querySelector('.workspace:not(.photo-workspace)').hidden=photo;$('typeMode').classList.toggle('active',!photo);$('photoMode').classList.toggle('active',photo);$('typeMode').setAttribute('aria-pressed',!photo);$('photoMode').setAttribute('aria-pressed',photo);window.history.replaceState(null,'',photo?'#photo':location.pathname+location.search);historyUI();}
// Existing lettering history is not modified when switching modes.
function historyUI(){if(!active){window.dispatchEvent(new Event('arbor:type-mode'));return;}$('undo').disabled=!past.length;$('redo').disabled=!future.length;$('saveProject').disabled=!source;$('exportBtn').disabled=!source;$('photoSave').disabled=!source;}
$('typeMode').onclick=()=>setMode(false);$('photoMode').onclick=()=>setMode(true);
function checkpoint(){const s=JSON.stringify(settings);if(past.at(-1)!==s){past.push(s);if(past.length>40)past.shift();}future=[];historyUI();}
function sync(){for(const [k]of Object.entries(rangeMap)){const r=$('photo-'+k),n=$('photo-n-'+k);r.value=settings[k];n.value=settings[k];r.style.setProperty('--fill',((settings[k]-r.min)/(r.max-r.min)*100)+'%');}$('photoSource').value=settings.source;$('photoInk').value=settings.ink;$('photoPaper').value=settings.paper;$('photoTransparent').checked=settings.transparent;document.querySelectorAll('[data-photo-preset]').forEach(b=>b.classList.toggle('active',b.dataset.photoPreset===currentPreset));historyUI();}
function compare(){const v=+$('photoCompareRange').value;$('photoBefore').style.clipPath=`inset(0 ${100-v}% 0 0)`;$('photoSeam').style.left=v+'%';$('photoSeam').hidden=v===0||v===100;$('photoCompare').classList.toggle('active',v>0);}
$('photoCompareRange').oninput=compare;$('photoCompare').onclick=()=>{if(!source)return notify('Сначала загрузи фото');$('photoCompareRange').value=+$('photoCompareRange').value?0:50;compare();};
function pixelsAt(max){const ratio=Math.min(1,max/Math.max(source.width,source.height)),c=document.createElement('canvas');c.width=Math.max(1,Math.round(source.width*ratio));c.height=Math.max(1,Math.round(source.height*ratio));const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,c.width,c.height);return {canvas:c,pixels:ctx.getImageData(0,0,c.width,c.height)};}
function runWorker(pixels,params,onWorker){return new Promise((resolve,reject)=>{const worker=new Worker('photo-worker.js');onWorker?.(worker);worker.onmessage=({data})=>{worker.terminate();if(data.error)reject(Error(data.error));else resolve(data);};worker.onerror=()=>{worker.terminate();reject(Error('Worker failed'));};worker.postMessage({id:revision,pixels:pixels.data,width:pixels.width,height:pixels.height,params},[pixels.data.buffer]);});}
function schedule(){if(!source)return;revision++;clearTimeout(timer);previewWorker?.terminate();$('photoBusy').hidden=false;timer=setTimeout(render,100);}
async function render(){if(!source)return;const id=revision;try{const {canvas,pixels}=pixelsAt(900),original=$('photoOriginal');original.width=canvas.width;original.height=canvas.height;original.getContext('2d').drawImage(canvas,0,0);$('photoStage').style.maxWidth=(680*canvas.width/canvas.height)+'px';const result=await runWorker(pixels,{...settings},w=>previewWorker=w);if(id!==revision)return;const out=$('photoOutput');out.width=result.width;out.height=result.height;out.getContext('2d').putImageData(new ImageData(result.pixels,result.width,result.height),0,0);renderedRevision=id;$('photoDimensions').textContent=`${source.width} × ${source.height} · превью ${out.width} × ${out.height}`;$('photoBusy').hidden=true;compare();}catch(error){if(id!==revision)return;$('photoBusy').hidden=true;notify('Не удалось обработать фото. Попробуй другое изображение.');console.error(error);}}
async function loadImage(blob,name,project=false){const id=++loadRevision;if(blob.size>(project?50:30)*1024*1024)throw Error('size');const url=URL.createObjectURL(blob);try{const img=new Image();await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url;});if(img.naturalWidth*img.naturalHeight>60e6)throw Error('dimensions');if(id!==loadRevision)return false;const ratio=Math.min(1,3000/Math.max(img.naturalWidth,img.naturalHeight));const c=document.createElement('canvas');c.width=Math.max(1,Math.round(img.naturalWidth*ratio));c.height=Math.max(1,Math.round(img.naturalHeight*ratio));c.getContext('2d').drawImage(img,0,0,c.width,c.height);setSource(c,name);return true;}finally{URL.revokeObjectURL(url);}}
function setSource(c,name){source=c;sourceName=name;past=[];future=[];$('photoDrop').hidden=true;$('photoPreview').hidden=false;$('photoSettings').disabled=false;$('photoName').textContent=name;$('photoCompareRange').value=0;sync();schedule();}
async function acceptFile(file){if(!file)return;try{await loadImage(file,file.name);}catch{notify('Не удалось открыть фото. Используй JPG, PNG, WebP или AVIF до 30 МБ.');}}
$('photoFile').onchange=async()=>{await acceptFile($('photoFile').files[0]);$('photoFile').value='';};$('photoUploadEmpty').onclick=$('photoReplace').onclick=()=>$('photoFile').click();
for(const name of ['dragenter','dragover'])area.addEventListener(name,e=>{e.preventDefault();area.classList.add('drop-hover');});area.addEventListener('dragleave',e=>{if(!area.contains(e.relatedTarget))area.classList.remove('drop-hover');});area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('drop-hover');acceptFile(e.dataTransfer.files[0]);});
for(const el of area.querySelectorAll('[data-photo-param]')){el.addEventListener('pointerdown',checkpoint);el.addEventListener('focus',()=>{if(el.type==='number')checkpoint();});el.addEventListener('keydown',e=>{if(e.key.startsWith('Arrow'))checkpoint();});el.addEventListener('input',()=>{if(el.value==='')return;settings[el.dataset.photoParam]=Math.max(+el.min,Math.min(+el.max,+el.value));currentPreset=null;sync();schedule();});}
area.querySelectorAll('[data-photo-preset]').forEach(b=>b.onclick=()=>{checkpoint();settings={...P.presets[b.dataset.photoPreset],seed:settings.seed,source:settings.source,transparent:settings.transparent};currentPreset=b.dataset.photoPreset;sync();schedule();});
$('photoSource').onchange=()=>{checkpoint();settings.source=$('photoSource').value;sync();schedule();};
for(const [id,key]of [['photoInk','ink'],['photoPaper','paper']]){$(id).addEventListener('pointerdown',checkpoint);$(id).oninput=()=>{settings[key]=$(id).value;schedule();};}
$('photoTransparent').onchange=()=>{checkpoint();settings.transparent=$('photoTransparent').checked;schedule();};$('photoInvert').onclick=()=>{checkpoint();[settings.ink,settings.paper]=[settings.paper,settings.ink];sync();schedule();};$('photoShuffle').onclick=()=>{if(!source)return;checkpoint();settings.seed=Math.floor(Math.random()*999999);schedule();};$('photoReset').onclick=()=>{checkpoint();settings={...P.defaults};currentPreset='lichen';sync();schedule();};
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function fileBase(){return 'arbor-photo-'+sourceName.replace(/\.[^.]+$/,'').replace(/[^\p{L}\p{N}-]+/gu,'-').slice(0,60);}
async function exportPhoto(type){if(!source||exporting)return;exporting=true;$('photoPng').disabled=$('photoJpeg').disabled=true;$('photoExportHint').textContent='Проявляем изображение в полном размере…';try{const {pixels}=pixelsAt(+$('photoExportSize').value);const result=await runWorker(pixels,{...settings,transparent:type==='image/png'&&settings.transparent});const c=document.createElement('canvas');c.width=result.width;c.height=result.height;c.getContext('2d').putImageData(new ImageData(result.pixels,c.width,c.height),0,0);const blob=await new Promise(resolve=>c.toBlob(resolve,type,.95));if(!blob)throw Error('export');download(blob,fileBase()+(type==='image/png'?'.png':'.jpg'));dialog.close();notify(`Фото сохранено · ${c.width} × ${c.height}`);}catch(error){notify('Экспорт не удался. Попробуй меньший размер.');console.error(error);}finally{exporting=false;$('photoPng').disabled=$('photoJpeg').disabled=false;$('photoExportHint').textContent='Пропорции исходного изображения сохраняются.';}}
$('photoPng').onclick=()=>exportPhoto('image/png');$('photoJpeg').onclick=()=>exportPhoto('image/jpeg');
function save(){if(!source)return;download(new Blob([JSON.stringify({format:'arbor-photo',version:1,name:sourceName,settings,image:source.toDataURL('image/png')})],{type:'application/json'}),fileBase()+'.arbor-photo.json');notify('Фотопроект сохранён вместе с изображением');}
$('photoSave').onclick=save;$('photoOpen').onclick=()=>$('photoProjectFile').click();
function validatePhoto(data){if(data?.format!=='arbor-photo'||data.version!==1||typeof data.image!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(data.image)||data.image.length>65000000)throw Error('project');const p={...P.defaults};for(const [k,{min,max}]of Object.entries(rangeMap)){const v=data.settings?.[k];if(v!==undefined){if(!Number.isFinite(v)||v<min||v>max)throw Error('range');p[k]=v;}}for(const k of ['ink','paper']){if(!/^#[0-9a-f]{6}$/i.test(data.settings?.[k]))throw Error('color');p[k]=data.settings[k];}if(!['dark','light','edges','tones'].includes(data.settings?.source))throw Error('source');p.source=data.settings.source;p.seed=Number.isInteger(data.settings.seed)&&data.settings.seed>=0&&data.settings.seed<=999999?data.settings.seed:2741;p.transparent=!!data.settings.transparent;return p;}
$('photoProjectFile').onchange=async()=>{const file=$('photoProjectFile').files[0];if(!file)return;try{if(file.size>66000000)throw Error('size');const data=JSON.parse(await file.text()),next=validatePhoto(data),base64=data.image.split(',')[1],raw=atob(base64),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));if(await loadImage(new Blob([bytes],{type:data.image.split(';')[0].slice(5)}),String(data.name||'photo').slice(0,100),true)){settings=next;currentPreset=null;sync();schedule();notify('Фотопроект открыт');}}catch{notify('Не удалось открыть фотопроект. Нужен файл .arbor-photo.json.');}finally{$('photoProjectFile').value='';}};
for(const [id,action]of [['undo',()=>{if(!past.length)return;future.push(JSON.stringify(settings));settings=JSON.parse(past.pop());currentPreset=null;sync();schedule();}],['redo',()=>{if(!future.length)return;past.push(JSON.stringify(settings));settings=JSON.parse(future.pop());currentPreset=null;sync();schedule();}],['saveProject',save],['exportBtn',()=>{if(source)dialog.showModal();}]])$(id).addEventListener('click',e=>{if(!active)return;e.stopImmediatePropagation();action();},true);
document.addEventListener('keydown',e=>{if(!active||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click();}});
$('photoDemo').onclick=()=>{const c=document.createElement('canvas');c.width=1000;c.height=750;const x=c.getContext('2d');x.fillStyle='#efeee8';x.fillRect(0,0,c.width,c.height);const stems=[[210,710,480,100],[550,730,710,120],[390,720,220,250]];stems.forEach(([sx,sy,ex,ey],n)=>{x.strokeStyle='#343d29';x.lineWidth=5;x.beginPath();x.moveTo(sx,sy);x.quadraticCurveTo(ex-90,sy-300,ex,ey);x.stroke();for(let i=1;i<8;i++){const t=i/8,cx=sx*(1-t)+ex*t-45*Math.sin(t*Math.PI),cy=sy*(1-t)+ey*t,side=i%2?1:-1;x.save();x.translate(cx,cy);x.rotate(-.9+side*.8);const grad=x.createLinearGradient(0,0,110,0);grad.addColorStop(0,'#131b11');grad.addColorStop(.55,'#526043');grad.addColorStop(1,'#7b8760');x.fillStyle=grad;x.beginPath();x.moveTo(0,0);x.bezierCurveTo(35,-55,100,-45,135,0);x.bezierCurveTo(70,50,35,40,0,0);x.fill();x.strokeStyle='#acb898';x.lineWidth=1;x.beginPath();x.moveTo(0,0);x.lineTo(127,0);x.stroke();x.restore();}});setSource(c,'Демо-рисунок — ботаника');};
sync();compare();if(location.hash==='#photo')setMode(true);
})();
